<?php
namespace Tests\Feature; use Illuminate\Support\Facades\Schema; use Tests\TestCase;
class TrainingCap3ArchitectureTest extends TestCase{public function test_snapshot_attempt_reinforcement_and_route_tables_exist():void{$this->assertTrue(Schema::hasColumns('training_evaluation_questions',['question_text','question_type','points','is_critical']));$this->assertTrue(Schema::hasColumns('training_evaluation_attempts',['attempt_number','percentage_score','result','status']));$this->assertTrue(Schema::hasTable('training_reinforcements'));$this->assertTrue(Schema::hasColumns('training_requirements',['validity_months','requires_evaluation','requires_certificate']));}public function test_attendance_domain_does_not_contain_learning_results():void{$this->assertFalse(Schema::hasColumn('attendance_records','score'));$this->assertFalse(Schema::hasColumn('attendance_records','passed'));$this->assertFalse(Schema::hasTable('training_signatures'));}public function test_public_evaluation_view_never_contains_correct_answer_flags():void{$source=file_get_contents(resource_path('views/training/evaluations/take.blade.php'));$this->assertStringNotContainsString('is_correct',$source);$this->assertStringNotContainsString('data-correct',$source);$this->assertStringNotContainsString('correctAnswers',$source);}}
